import '@fontsource-variable/inter';
import '../stories/_lib/story.css';
import '@xy-lit/flow/define.js';
import { html } from 'lit';
import { ref } from 'lit/directives/ref.js';
import { setCustomElementsManifest } from '@storybook/web-components';
import type { Preview } from '@storybook/web-components-vite';

// ---- custom elements manifest (generated by `scripts/manifest.ts`; optional) --------------------

type Manifest = {
  schemaVersion: string;
  modules: { declarations?: { customElement?: boolean; name: string; tagName?: string }[] }[];
};
const parts = import.meta.glob<Manifest>('../.manifests/*/custom-elements.json', {
  eager: true,
  import: 'default',
});
const modules = Object.values(parts).flatMap((m) => m.modules ?? []);
// the analyzer cannot see tag names (they are registered in a loop in each `define.ts`): derive
// them from the class names, `XyNodeResizerElement` -> `xy-node-resizer`
for (const mod of modules) {
  for (const decl of mod.declarations ?? []) {
    const match = /^(Xy[A-Za-z]+)Element$/.exec(decl.name);
    if (decl.customElement && !decl.tagName && match?.[1]) {
      decl.tagName = match[1].replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
    }
  }
}
if (modules.length > 0) setCustomElementsManifest({ schemaVersion: '1.0.0', modules });

// ---- colour mode ---------------------------------------------------------------------------------

/**
 * Keeps `color-mode` of every `<xy-flow>` inside the story frame in step with the toolbar. The
 * observer also catches flows that stories add later (and flows inside light-DOM story elements).
 * A flow with `data-fixed-mode` keeps its own mode.
 */
function trackColorMode(frame: Element | undefined): void {
  if (!frame) return;
  const el = frame as HTMLElement & { __xyObserver?: MutationObserver };
  if (el.__xyObserver) return;
  const sync = (): void => {
    const mode = el.dataset.mode ?? 'light';
    for (const flow of el.querySelectorAll('xy-flow')) {
      if (flow.hasAttribute('data-fixed-mode')) continue;
      if (flow.getAttribute('color-mode') !== mode) flow.setAttribute('color-mode', mode);
    }
  };
  el.__xyObserver = new MutationObserver(sync);
  el.__xyObserver.observe(el, {
    childList: true,
    subtree: true,
    attributes: true,
    attributeFilter: ['data-mode'],
  });
  sync();
}

const preview: Preview = {
  tags: ['autodocs'],
  globalTypes: {
    colorMode: {
      description: 'Colour mode of every flow and the canvas',
      toolbar: {
        title: 'Colour mode',
        icon: 'circlehollow',
        items: [
          { value: 'light', title: 'Light', icon: 'sun' },
          { value: 'dark', title: 'Dark', icon: 'moon' },
        ],
        dynamicTitle: true,
      },
    },
  },
  initialGlobals: { colorMode: 'light' },
  decorators: [
    (story, context) => {
      const mode = (context.globals.colorMode as string | undefined) === 'dark' ? 'dark' : 'light';
      document.documentElement.dataset.xyMode = mode;
      document.body.style.background = mode === 'dark' ? '#141414' : '#ffffff';
      const height = (context.parameters.frame as { height?: number } | undefined)?.height ?? 520;
      // every story renders in a 100% x 520px frame (spec/16); a story may ask for more
      return html`<div
        class="sb-frame"
        data-mode=${mode}
        style="height:${height}px"
        ${ref(trackColorMode)}
      >
        ${story()}
      </div>`;
    },
  ],
  parameters: {
    layout: 'fullscreen',
    controls: { expanded: true, sort: 'alpha' },
    docs: { source: { type: 'code' } },
    a11y: { test: 'todo' },
    options: {
      storySort: {
        order: [
          'Introduction',
          'Flow',
          ['Basics', 'Interaction', 'Sub-flows', 'Edges', 'Nodes', 'Lifecycle'],
          'Plugins',
          'Collaboration',
          'Pro',
          'UI',
        ],
      },
    },
  },
};

export default preview;
